 const snapshot=(p:Project=project,quiet=false)=>{const v={id:crypto.randomUUID(),name:`${p.name} · v${versions.filter(v=>v.project.id===p.id).length+1}`,date:Date.now(),project:structuredClone(p)};setVersions(vs=>[v,...vs]);if(!quiet)toast.success(t('Saved a version to the Archive.'),{action:{label:t('View'),onClick:()=>navigate('Archive')}})};
 const duplicateProject=(p:Project)=>{const copy=copyProject(p,t('{name} copy',{name:p.name}));setProjects(ps=>[copy,...ps]);toast.success(t('Duplicated the project.'),{action:{label:t('Open'),onClick:()=>openProject(copy.id)}})};
 // Restoring saves the project's current state as a version first, so it can be undone.
 const restoreVersion=(v:Version)=>{const current=projects.find(p=>p.id===v.project.id);setConfirm({title:t('Restore this version?'),body:current?t('“{name}” will be replaced with this version. Its current state is saved to the Archive first.',{name:current.name}):t('The project will be restored from this version.'),action:t('Restore'),run:()=>{if(current)snapshot(current,true);const restored:Project={...structuredClone(v.project),rev:current?.rev,updated:Date.now(),scenes:v.project.scenes.map(s=>({...structuredClone(s),gen:undefined})),jobs:undefined};setProjects(ps=>current?ps.map(p=>p.id===current.id?restored:p):[...ps,restored]);openProject(restored.id,'Storyboard');setSelected(restored.scenes[0]?.id||'');toast.success(t('Restored the version.'),current?{action:{label:t('Undo'),onClick:()=>setProjects(ps=>ps.map(p=>p.id===current.id?{...current,rev:p.rev,updated:Date.now()}:p))}}:undefined)}})};
 const copyVersion=(v:Version)=>{const copy=copyProject(v.project,t('{name} copy',{name:v.project.name}));setProjects(ps=>[copy,...ps]);toast.success(t('Created a project from this version.'),{action:{label:t('Open'),onClick:()=>openProject(copy.id)}})};
 const deleteVersion=(v:Version)=>setConfirm({title:t('Delete this version?'),body:t('“{name}” will be removed from the Archive. This can’t be undone.',{name:v.name}),action:t('Delete'),danger:true,run:async()=>{try{await api.deleteVersion(v.id);setVersions(vs=>vs.filter(x=>x.id!==v.id));toast.success(t('Deleted the version.'))}catch(e){toast.error(t('Could not delete: {m}',{m:(e as Error).message}))}}});
 const deleteProject=(p:Project)=>setConfirm({title:t('Delete this project?'),body:t('“{name}” and its scenes will be deleted. Its media stays in the Library and saved versions stay in the Archive.',{name:p.name}),action:t('Delete project'),danger:true,run:async()=>{try{if(p.rev!==undefined)await api.deleteProject(p.id);const rest=projects.filter(x=>x.id!==p.id);setProjects(rest.length?rest:[blankProject(t('Untitled project'))]);if(p.id===project.id){const next=rest.filter(isListedProject).sort((a,b)=>b.updated-a.updated)[0];if(next)setProjectId(next.id);else{setProjectId('');setShowLanding(true)}setSelected('')}toast.success(t('Deleted the project.'))}catch(e){toast.error(t('Could not delete: {m}',{m:(e as Error).message}))}}});
 const uploadFiles=async(files:FileList|File[]|null,source:'upload'|'recording'='upload',asFrame=false):Promise<Asset[]>=>{const done:Asset[]=[];if(!files)return done;const list=Array.from(files);if(inputRef.current)inputRef.current.value='';if(frameInputRef.current)frameInputRef.current.value='';for(const file of list){if(!/^(image|video|audio)\//.test(file.type)){toast.error(t('{name}: only images, video and audio are supported.',{name:file.name}));continue}if(file.size>200*1024*1024){toast.error(t('Files can be up to 200 MB each.'));continue}const pending=toast.loading(t('Uploading {name}…',{name:file.name}));try{const a=await api.upload(file,{projectId:showLanding?undefined:project.id,source});upsertAsset(a);setTrashed(ids=>ids.filter(x=>x!==a.id));setAssetId(a.id);if(!showLanding)update(p=>({...p,assetIds:[...new Set([...(p.assetIds||[]),a.id])]}));if(showLanding&&!asFrame)setLandingAssetId(a.id);done.push(a);toast.success(t('{name} added',{name:file.name}),{id:pending})}catch(e){toast.error(t('Could not save the file.')+' '+(e as Error).message,{id:pending})}}return done};
 // First / last frame of the video (composer), or the last frame of one scene (Scene details).
 const setFrame=(slot:FrameSlot|'scene-end',id?:string)=>{if(slot==='scene-end'){updateScene({endAssetId:id});if(id)update(p=>({...p,assetIds:[...new Set([...(p.assetIds||[]),id])]}));return}if(showLanding){setLandingFrames(f=>({...f,[slot]:id}));return}update(p=>({...p,[slot==='first'?'firstFrameId':'lastFrameId']:id,assetIds:id?[...new Set([...(p.assetIds||[]),id])]:p.assetIds}))};
 const pickFrame=(slot:FrameSlot|'scene-end',via:'upload'|'library')=>{setFrameSlot(slot);if(via==='upload')frameInputRef.current?.click();else setDialog('frame')};
 const frameAssets=(ids:Partial<Record<FrameSlot,string|undefined>>)=>({first:assets.find(a=>a.id===ids.first),last:assets.find(a=>a.id===ids.last)});
 const scenePatch=(patch:Record<string,any>):Partial<Scene>=>{const out:Partial<Scene>={};for(const k of ['name','script','caption','prompt'] as const)if(typeof patch[k]==='string')out[k]=patch[k];if(['Still','Push in','Pan left'].includes(patch.motion))out.motion=patch.motion;if(['Cut','Fade'].includes(patch.transition))out.transition=patch.transition;if(Number.isFinite(Number(patch.duration))&&Number(patch.duration)>0)out.duration=Number(patch.duration);if(out.prompt!==undefined)out.videoPrompt=undefined;return out};
 const applyActions=async(pid:string,actions:ChatAction[],mode:string)=>{for(const a of actions){if(a.type==='update_scene'){setProjects(ps=>ps.map(p=>p.id===pid?{...p,updated:Date.now(),scenes:p.scenes.map(s=>s.id===a.scene_id?normalizeScene(s,assetsRef.current.find(x=>x.id===s.assetId),scenePatch(a.patch)):s)}:p))}else if(a.type==='plan'){if(pid===projectId)changeStudioView('Storyboard');await ai.startPlan(pid,a.brief,{mode:mode==='auto'?'auto':'manual'})}else if(a.type==='generate'){if(mode==='auto')await ai.generateScenes(pid,a.scene_ids,a.stage,{autoExport:a.stage!=='image'});else toast(t('Ready to generate. Start now?'),{action:{label:t('Generate'),onClick:()=>void ai.generateScenes(pid,a.scene_ids,a.stage)}})}else if(a.type==='voiceover'){await ai.voiceover(pid,a.script)}else if(a.type==='music'){await ai.music(pid,a.prompt)}}};
 const send=async()=>{const text=draft.trim();if(!text||chatBusy||projectGenerating)return;const pid=project.id;const g={...generation};update(p=>({...p,messages:[...p.messages,{id:crypto.randomUUID(),role:'user',text,generation:g}]}));setDraft('');setChatBusy(true);try{await new Promise(r=>setTimeout(r,0));await sync.flush(pid);const res=await api.chat(pid,{text,model:g.model,mode:g.mode,language:lang,selected_scene_id:scene?.id,generation:g});setProjects(ps=>ps.map(p=>p.id===pid?{...p,messages:[...p.messages,{id:res.agent_message.id,role:'agent',text:res.agent_message.text}],updated:Date.now()}:p));await applyActions(pid,res.actions,g.mode)}catch(e){toast.error((e as Error).message)}finally{setChatBusy(false)}};
 const playback=()=>{if(!scene)return;const next=!playing;const restarting=next&&elapsed>=total;if(restarting){setSelected(project.scenes[0].id);setPlayhead(0)}setPlaying(next);if(next){[musicRef.current,voiceRef.current].forEach(a=>{if(a?.getAttribute('src')){a.currentTime=restarting?0:elapsed;a.play().catch(()=>toast.error(t('Could not play the audio.')))}})}if(videoRef.current){if(next){videoRef.current.currentTime=(scene.sourceIn||0)+(restarting?0:playhead);videoRef.current.play().catch(()=>{setPlaying(false);toast.error(t('Could not play the video.'))})}else videoRef.current.pause()}};
 const exportProject=()=>downloadBlob(new Blob([JSON.stringify({format:'palette-project',version:1,project,assets:assets.map(({src,...a})=>({...a,src:a.uploaded?undefined:src}))},null,2)],{type:'application/json'}),`${project.name}.palette.json`);
 const exportCaptions=()=>{const captions:{start:number;end:number;text:string}[]=[...(project.captions||[])];let at=0;project.scenes.forEach(s=>{if(s.caption)captions.push({start:at,end:at+s.duration,text:s.caption});at+=s.duration});if(!captions.length){toast.error(t('Add captions to your scenes first.'));return}downloadBlob(new Blob([captions.sort((a,b)=>a.start-b.start).map((c,i)=>`${i+1}\n${srtTime(c.start)} --> ${srtTime(c.end)}\n${c.text}\n`).join('\n')],{type:'text/plain'}),`${project.name}.srt`)};
 const autoExport=async(projectId:string)=>{const p=projectsRef.current.find(x=>x.id===projectId);if(!p)return;if(!catalog.ffmpeg){toast.error(t('Video export isn’t available right now.'));return}const g=generationSettings(p.generation);setExporting(true);setExportResult(null);try{await sync.flush(projectId);const {generation_id}=await api.exportProject(projectId,{ratio:g.ratio,resolution:g.resolution,bitrate:g.bitrate,burn_captions:true,name:`${p.name} · ${new Date().toLocaleTimeString(locale)}`});setExportJob({id:generation_id})}catch(e){setExporting(false);toast.error(t((e as Error).message))}};
 autoExportRef.current=id=>{void autoExport(id)};
 const exportMovie=async()=>{if(!catalog.ffmpeg){toast.error(t('Video export isn’t available right now.'));return}setExporting(true);setPlaying(false);setExportResult(null);try{await sync.flush(project.id);const {generation_id}=await api.exportProject(project.id,{ratio:generation.ratio,resolution:generation.resolution,bitrate:generation.bitrate,burn_captions:true,name:`${project.name} · ${new Date().toLocaleTimeString(locale)}`});setExportJob({id:generation_id})}catch(e){setExporting(false);toast.error(t((e as Error).message))}};
 const startRecording=async(kind:'screen'|'voice')=>{try{const stream=kind==='screen'?await navigator.mediaDevices.getDisplayMedia({video:true,audio:true}):await navigator.mediaDevices.getUserMedia({audio:true});streamRef.current=stream;const rec=new MediaRecorder(stream);recordRef.current=rec;const chunks:BlobPart[]=[];rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};rec.onstop=()=>{stream.getTracks().forEach(t=>t.stop());setRecording(false);const mime=rec.mimeType|| (kind==='voice'?'audio/webm':'video/webm');uploadFiles([new File(chunks,`${t(kind==='voice'?'Voice':'Screen')} ${new Date().toLocaleTimeString(locale)}.webm`,{type:mime})],'recording')};stream.getVideoTracks()[0]?.addEventListener('ended',()=>{if(rec.state!=='inactive')rec.stop()});rec.start();setRecording(true);setDialog('record')}catch{toast.error(t('Recording permission was denied, or this browser is not supported.'))}};
 const previewVoice=()=>{if(!scene?.script.trim()){toast.error(t('Enter a script first.'));return}if(!('speechSynthesis'in window)){toast.error(t('Voice preview is not supported.'));return}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(scene.script);utterance.lang=lang==='ko'?'ko-KR':'en-US';utterance.voice=voices.find(v=>v.voiceURI===voice)||null;speechSynthesis.speak(utterance)};
