 // Library → current project: the media becomes a new scene on the storyboard.
 const addToProject=(id:string)=>{const a=assets.find(x=>x.id===id);if(!a)return;if(a.type==='audio'){update(p=>({...p,assetIds:[...new Set([...(p.assetIds||[]),id])]}));toast.success(t('Added to “{name}” media.',{name:project.name}),{action:{label:t('Open'),onClick:()=>{openProject(project.id,'Media');setCategory('Voices & audio')}}});return}addScene(id);toast.success(t('Added a scene to “{name}”.',{name:project.name}),{action:{label:t('Open'),onClick:()=>openProject(project.id,'Storyboard')}})};
