 // One handler for every Library picker: what a pick does depends on why the drawer was opened.
 const pickMedia=(a:Asset)=>{if(dialog==='frame'){setFrame(frameSlot,a.id);setDialog('');return}setAssetId(a.id);if(dialog==='add'){addScene(a.id);return}setDialog('');if(dialog==='replace'){if(scene){updateScene({assetId:a.id});update(p=>({...p,assetIds:[...new Set([...(p.assetIds||[]),a.id])]}))}else addScene(a.id);return}if(dialog==='pick'&&showLanding){setLandingAssetId(a.id);return}addMediaToProject(a)};
